window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[124]={"id":"124","numero":124,"titre":"Ménopause - andropause","objectifs":[{"id":"124-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la périménopause et ménopause","contenu":"<p>La <span class=\"kw-def\">ménopause</span> est l'<strong>arrêt définitif des règles</strong> par <span class=\"kw-def\">épuisement du capital folliculaire ovarien</span>. C'est un <span class=\"kw-def\">diagnostic rétrospectif</span>, posé après une <span class=\"kw-clinique\">aménorrhée</span> d'au moins <span class=\"kw-chiffre\">12 mois</span> consécutifs.</p>\n      <p>La <span class=\"kw-def\">périménopause</span> est la <strong>période de transition</strong> qui précède la ménopause et s'étend jusqu'à <span class=\"kw-chiffre\">12 mois</span> après les dernières règles : <span class=\"kw-clinique\">cycles irréguliers</span> (raccourcis puis allongés), <span class=\"kw-clinique\">signes climatériques</span> débutants, persistance possible de <span class=\"kw-clinique\">menstruations sporadiques</span> après une phase d'<span class=\"kw-clinique\">aménorrhée</span>. Elle traduit l'<span class=\"kw-bio\">épuisement folliculaire</span> progressif.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span> (STRAW+10)</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Périménopause / transition</strong></td><td><span class=\"kw-clinique\">cycles irréguliers</span> ; variabilité de la durée &gt; <span class=\"kw-chiffre\">7 jours</span> ; <span class=\"kw-bio\">FSH</span> fluctuante</td></tr>\n          <tr><td><strong>Ménopause</strong></td><td><span class=\"kw-clinique\">aménorrhée</span> ≥ <span class=\"kw-chiffre\">12 mois</span> ; date posée a posteriori</td></tr>\n          <tr><td><strong>Post-ménopause</strong></td><td><span class=\"kw-bio\">hypoœstrogénie</span> installée ; <span class=\"kw-bio\">FSH</span> élevée stable</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":2},{"id":"124-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques épidémiologiques de la ménopause naturelle","contenu":"<ul>\n        <li><span class=\"kw-def\">Âge moyen</span> de la ménopause naturelle en France : <span class=\"kw-chiffre\">50 à 52 ans</span>.</li>\n        <li>Environ <span class=\"kw-chiffre\">10 millions</span> de <span class=\"kw-clinique\">femmes ménopausées</span> en France.</li>\n        <li><span class=\"kw-clinique\">Espérance de vie</span> féminine ≈ <span class=\"kw-chiffre\">85 ans</span> → près d'<strong><span class=\"kw-chiffre\">1/3 de la vie</span></strong> passé en <span class=\"kw-clinique\">post-ménopause</span>.</li>\n        <li><span class=\"kw-def\">Ménopause précoce</span> = avant <span class=\"kw-chiffre\">40 ans</span> (= <span class=\"kw-etio\">insuffisance ovarienne prématurée</span>) ; <span class=\"kw-def\">ménopause tardive</span> = après <span class=\"kw-chiffre\">55 ans</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la définition et les modalités du diagnostic d’une insuffisance ovarienne prématurée","contenu":"<p>L'<span class=\"kw-def\">insuffisance ovarienne prématurée (IOP)</span> est la <strong>perte de la <span class=\"kw-clinique\">fonction ovarienne</span> avant <span class=\"kw-chiffre\">40 ans</span></strong>. <span class=\"kw-clinique\">Prévalence</span> ≈ <span class=\"kw-chiffre\">1 %</span> de la population générale.</p>\n      <p><strong><span class=\"kw-def\">Critères diagnostiques</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Aménorrhée</span> ou <span class=\"kw-clinique\">oligo-/spanioménorrhée</span> depuis ≥ <span class=\"kw-chiffre\">4 mois</span></li>\n        <li><span class=\"kw-bio\">FSH</span> &gt; <span class=\"kw-chiffre\">25 UI/L</span> sur <strong>deux prélèvements</strong> à ≥ <span class=\"kw-chiffre\">4 semaines</span> d'intervalle</li>\n      </ul>\n      <table >\n        <thead><tr><th>Étiologies</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Iatrogènes</strong></td><td><span class=\"kw-etio\">chirurgie ovarienne</span> ; <span class=\"kw-etio\">radiothérapie</span> ; <span class=\"kw-etio\">chimiothérapie</span></td></tr>\n          <tr><td><strong>Génétiques</strong></td><td><span class=\"kw-etio\">syndrome de Turner</span> ; <span class=\"kw-etio\">prémutation FMR1</span> (X fragile)</td></tr>\n          <tr><td><strong>Auto-immunes</strong></td><td><span class=\"kw-etio\">ovarite auto-immune</span> ; polyendocrinopathies</td></tr>\n          <tr><td><strong>Idiopathique</strong></td><td>cause non retrouvée (fréquent)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Dans l'IOP, le <span class=\"kw-ttt\">THM est indispensable</span> jusqu'à l'âge physiologique de la ménopause (~<span class=\"kw-chiffre\">51 ans</span>) : surrisque <span class=\"kw-alerte\">cardiovasculaire</span> et <span class=\"kw-alerte\">osseux</span> si non traitée. Des <span class=\"kw-clinique\">grossesses spontanées</span> restent possibles mais rares.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic de ménopause","contenu":"<p>Le diagnostic de ménopause est <strong><span class=\"kw-def\">clinique</span></strong> : <span class=\"kw-clinique\">aménorrhée</span> ≥ <span class=\"kw-chiffre\">12 mois</span> chez une femme vers <span class=\"kw-chiffre\">50 ans</span>, associée au <span class=\"kw-clinique\">syndrome climatérique</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Dosages hormonaux non systématiques.</strong> Inutiles si la clinique suffit. Réservés aux situations difficiles : <span class=\"kw-clinique\">hystérectomie</span> (pas de repère menstruel), âge inhabituel (&lt; <span class=\"kw-chiffre\">50 ans</span>), doute diagnostique.\n      </div>\n      <ul>\n        <li>Si bilan réalisé : <span class=\"kw-bio\">FSH</span> &gt; <span class=\"kw-chiffre\">20 UI/L</span> et <span class=\"kw-bio\">estradiol (E2)</span> &lt; <span class=\"kw-chiffre\">20 pg/mL</span>.</li>\n        <li><strong><span class=\"kw-bio\">Test au progestatif</span></strong> (si aménorrhée &lt;<span class=\"kw-chiffre\"> 12 mois</span>) : progestatif <span class=\"kw-chiffre\">10-12 jours</span> → <span class=\"kw-clinique\">test négatif</span> (absence d'hémorragie de privation) = confirme l'<span class=\"kw-bio\">hypoœstrogénie</span>. Un test positif témoigne d'une activité ovarienne persistante.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":2},{"id":"124-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes du syndrome climatérique","contenu":"<p>Le <span class=\"kw-clinique\">syndrome climatérique</span> regroupe les conséquences de l'<span class=\"kw-bio\">hypoœstrogénie</span>. Intensité <strong>très variable</strong> d'une femme à l'autre.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Symptômes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Vasomoteur</strong></td><td><span class=\"kw-clinique\">bouffées de chaleur</span> (≈ <span class=\"kw-chiffre\">65 %</span> des femmes) ; <span class=\"kw-clinique\">sueurs nocturnes</span></td></tr>\n          <tr><td><strong>Génito-urinaire</strong></td><td><span class=\"kw-clinique\">sécheresse vaginale</span> ; <span class=\"kw-clinique\">dyspareunie</span> ; <span class=\"kw-clinique\">troubles urinaires</span></td></tr>\n          <tr><td><strong>Général</strong></td><td><span class=\"kw-clinique\">troubles du sommeil</span> ; <span class=\"kw-clinique\">céphalées</span> ; <span class=\"kw-clinique\">arthralgies</span></td></tr>\n          <tr><td><strong>Psycho-affectif</strong></td><td><span class=\"kw-clinique\">troubles de l'humeur</span> ; <span class=\"kw-clinique\">irritabilité</span> ; <span class=\"kw-clinique\">baisse de la libido</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-6","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir distinguer des bouffées de chaleur typiques et atypiques","contenu":"<p><strong>Bouffées de chaleur <span class=\"kw-def\">typiques</span> (climatériques) :</strong></p>\n      <ul>\n        <li>Sensation de <span class=\"kw-clinique\">chaleur ascendante</span> (visage, cou, thorax), suivie de <span class=\"kw-clinique\">sueurs</span> puis <span class=\"kw-clinique\">frissons</span>.</li>\n        <li>Volontiers <span class=\"kw-clinique\">nocturnes</span> ; déclenchées par les émotions/la chaleur.</li>\n        <li>Surviennent vers <span class=\"kw-chiffre\">50-55 ans</span> ; régressent spontanément en <span class=\"kw-chiffre\">5 à 7 ans</span> dans la majorité des cas.</li>\n      </ul>\n      <p><strong>Bouffées <span class=\"kw-alerte\">atypiques</span> (drapeaux → cause non climatérique) :</strong></p>\n      <table >\n        <thead><tr><th>Cause à évoquer</th><th>Ce qui doit alerter</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Phéochromocytome</span></strong></td><td>caractère <span class=\"kw-clinique\">paroxystique</span> ; <span class=\"kw-clinique\">triade de Ménard</span> (<span class=\"kw-clinique\">céphalées</span> + <span class=\"kw-clinique\">sueurs</span> + <span class=\"kw-clinique\">palpitations</span>) ; <span class=\"kw-clinique\">HTA variable</span> → <span class=\"kw-bio\">métanéphrines</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Syndrome carcinoïde</span> / TNE</strong></td><td><span class=\"kw-clinique\">flush + diarrhée</span> associés → <span class=\"kw-bio\">5-HIAA urinaires</span> élevés</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Cancer médullaire thyroïde</span></strong></td><td><span class=\"kw-clinique\">flush ± diarrhée</span> (calcitonine) ; forme déjà métastatique ; contexte NEM2</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Thyrotoxicose</span></strong></td><td><span class=\"kw-clinique\">thermophobie</span> + <span class=\"kw-clinique\">hypersudation permanentes</span> ; <span class=\"kw-clinique\">tachycardie</span> ; <span class=\"kw-clinique\">amaigrissement</span> → <span class=\"kw-bio\">TSH</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Une bouffée <span class=\"kw-clinique\">climatérique</span> est <strong>isolée</strong> et rythmée par la ménopause. Tout <span class=\"kw-alerte\">signe associé</span> (<span class=\"kw-etio\">HTA</span> paroxystique, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">amaigrissement</span>) ou caractère <span class=\"kw-clinique\">permanent/unilatéral</span> doit faire chercher une cause secondaire.\n      </div>\n      <p class=\"obj-source\"><em>Bouffées typiques : Collège de Gynécologie-obstétrique. Drapeaux atypiques : Collège d'Endocrinologie (chapitres phéochromocytome, TNE, thyrotoxicose — transversal).</em></p>","frequence":0},{"id":"124-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’hypoœstrogénie, d’hyperœstrogénie","contenu":"<p><strong>Signes d'<span class=\"kw-bio\">hypoœstrogénie</span></strong> (situation de la femme ménopausée) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Atrophie vulvo-vaginale</span> : sécheresse, <span class=\"kw-clinique\">dyspareunie</span>, <span class=\"kw-clinique\">prurit</span>.</li>\n        <li>Au spéculum : <span class=\"kw-clinique\">glaire cervicale absente</span> (test au progestatif négatif).</li>\n        <li><span class=\"kw-clinique\">Troubles urinaires</span> : dysurie, urgenturie, incontinence.</li>\n        <li><span class=\"kw-clinique\">Bouffées de chaleur</span> ; <span class=\"kw-clinique\">vieillissement cutané</span> et des phanères.</li>\n      </ul>\n      <p><strong>Signes d'<span class=\"kw-def\">hyperœstrogénie</span></strong> (imprégnation œstrogénique excessive ou non opposée) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Mastodynie</span> / tension mammaire (signe le plus direct).</li>\n        <li><span class=\"kw-clinique\">Ménométrorragies</span> fonctionnelles ; <span class=\"kw-alerte\">hyperplasie endométriale</span>.</li>\n        <li><span class=\"kw-clinique\">Glaire cervicale abondante</span> ; <span class=\"kw-clinique\">rétention hydrosodée</span> (<span class=\"kw-clinique\">œdèmes</span>, prise de poids, gonflement abdominal).</li>\n        <li>Sous THM = signes de <span class=\"kw-ttt\">surdosage œstrogénique</span> ; <span class=\"kw-clinique\">irritabilité</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Conséquence clé.</strong> L'<span class=\"kw-alerte\">hyperœstrogénie non opposée</span> (sans progestatif) favorise l'<span class=\"kw-alerte\">hyperplasie puis le cancer de l'endomètre</span> → justifie l'ajout systématique d'un <span class=\"kw-ttt\">progestatif</span> chez la femme non hystérectomisée sous œstrogènes.\n      </div>\n      <p class=\"obj-source\"><em>Hypoœstrogénie : Collège de Gynécologie-obstétrique. Hyperœstrogénie : Collège d'Endocrinologie (item 124, surdosage œstrogénique du THM).</em></p>","frequence":1},{"id":"124-8","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les effets de la ménopause à court, moyen et long terme","contenu":"<table >\n        <thead><tr><th>Échéance</th><th>Effets de l'hypoœstrogénie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Court terme</strong></td><td><span class=\"kw-clinique\">syndrome climatérique</span> : <span class=\"kw-clinique\">bouffées de chaleur</span> ; <span class=\"kw-clinique\">sueurs</span> ; <span class=\"kw-clinique\">troubles du sommeil et de l'humeur</span></td></tr>\n          <tr><td><strong>Moyen terme</strong></td><td><span class=\"kw-clinique\">atrophie vulvo-vaginale</span> ; <span class=\"kw-clinique\">troubles urinaires</span> ; modifications <span class=\"kw-clinique\">cutanées</span> ; <span class=\"kw-clinique\">prise de poids</span> à répartition androïde</td></tr>\n          <tr><td><strong>Long terme</strong></td><td><span class=\"kw-alerte\">ostéoporose post-ménopausique</span> (perte osseuse <span class=\"kw-chiffre\">1 à 2 %/an</span>) ; ↑ <span class=\"kw-alerte\">risque cardiovasculaire</span> (<span class=\"kw-etio\">athérosclérose</span> coronarienne)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> L'<span class=\"kw-alerte\">ostéoporose</span> est la complication majeure à long terme : risque de <span class=\"kw-alerte\">fracture du col fémoral</span> qui double tous les <span class=\"kw-chiffre\">5 ans</span> après <span class=\"kw-chiffre\">60 ans</span> ; ~1 femme sur 4 &gt;<span class=\"kw-chiffre\"> 80 ans</span> en est victime.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement hormonal de la ménopause (THM)","contenu":"<p>Le <span class=\"kw-ttt\">THM</span> associe un <span class=\"kw-ttt\">œstrogène</span> et, si <strong>utérus en place</strong>, un <span class=\"kw-ttt\">progestatif</span>.</p>\n      <ul>\n        <li><strong>Œstrogène :</strong> <span class=\"kw-ttt\">17β-estradiol</span> (œstrogène naturel), <span class=\"kw-clinique\">voie transdermique</span> (gel/patch) <strong>privilégiée</strong> → pas de premier passage hépatique, <span class=\"kw-alerte\">moindre risque thromboembolique</span>. Voie orale possible mais ↑ <span class=\"kw-bio\">triglycérides</span> et facteurs de coagulation.</li>\n        <li><strong>Progestatif :</strong> <span class=\"kw-ttt\">obligatoire si utérus en place</span> (protège l'endomètre du risque d'<span class=\"kw-alerte\">hyperplasie / cancer</span>). Privilégier <span class=\"kw-ttt\">progestérone naturelle</span> ou <span class=\"kw-ttt\">dydrogestérone</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Schéma</th><th>Modalités</th><th>Pour qui</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Séquentiel</strong> (« avec règles »)</td><td><span class=\"kw-ttt\">œstrogène</span> en continu + <span class=\"kw-ttt\">progestatif</span> 12-14 j/mois → <span class=\"kw-clinique\">hémorragie de privation</span></td><td>périménopause / femme non encore en aménorrhée</td></tr>\n          <tr><td><strong>Combiné continu</strong> (« sans règles »)</td><td><span class=\"kw-ttt\">œstrogène</span> + <span class=\"kw-ttt\">progestatif</span> en continu → <strong>pas de règles</strong></td><td>femme ménopausée installée</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":1},{"id":"124-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les examens complémentaires nécessaires avant utilisation d’un THM","contenu":"<ul>\n        <li><strong><span class=\"kw-imagerie\">Mammographie</span></strong> de moins de <span class=\"kw-chiffre\">1 an</span> (indispensable avant THM).</li>\n        <li><strong><span class=\"kw-bio\">Frottis cervico-utérin</span></strong> si le dernier date de ≥ <span class=\"kw-chiffre\">3 ans</span>.</li>\n        <li><strong><span class=\"kw-bio\">Bilan lipidique</span></strong> (CT, <span class=\"kw-bio\">LDL</span>, <span class=\"kw-bio\">HDL</span>, <span class=\"kw-bio\">triglycérides</span>) + <span class=\"kw-bio\">glycémie à jeun</span>.</li>\n        <li>Recherche d'une <span class=\"kw-bio\">carence en vitamine D</span>.</li>\n        <li><span class=\"kw-imagerie\">Ostéodensitométrie</span> si <span class=\"kw-def\">facteurs de risque</span> d'<span class=\"kw-alerte\">ostéoporose</span> ; <span class=\"kw-imagerie\">échographie pelvienne</span> si signe d'appel (métrorragies, <span class=\"kw-clinique\">masse</span>).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les contre-indications du THM","contenu":"<p><strong><span class=\"kw-ci\">Contre-indications</span> <span class=\"kw-def\">absolues</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-ci\">Cancer du sein</span> (actuel ou antécédent personnel) ; <span class=\"kw-ci\">cancer de l'endomètre</span>.</li>\n        <li>Antécédent personnel d'accident <span class=\"kw-ci\">thrombo-embolique artériel</span> (<span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-alerte\">IDM</span>) <strong>ou veineux</strong> (TVP proximale, EP).</li>\n        <li><span class=\"kw-ci\">Affection hépatique grave et évolutive</span>.</li>\n        <li><span class=\"kw-ci\">Hyperlipidémie sévère</span> ; <span class=\"kw-ci\">HTA grave</span> non contrôlée.</li>\n      </ul>\n      <p><strong>Évaluation individuelle bénéfice-risque</strong> (pas une <span class=\"kw-ci\">CI absolue</span>) : <span class=\"kw-etio\">myome</span>, <span class=\"kw-etio\">endométriose</span>, <span class=\"kw-etio\">mastopathie bénigne à risque</span>, <span class=\"kw-def\">facteurs de risque</span> vasculaire (<span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">migraine</span>), <span class=\"kw-etio\">cholestase</span>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":1},{"id":"124-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître la balance bénéfice-risque du THM en cas de ménopause naturelle et en cas d’insuffisance ovarienne prématurée et les alternatives au THM","contenu":"<ul>\n        <li><strong>Ménopause naturelle :</strong> THM proposé si <span class=\"kw-clinique\">syndrome climatérique altérant la qualité de vie</span>, après information éclairée, à <span class=\"kw-ttt\">dose minimale efficace</span> et durée la plus courte. <strong>Non recommandé</strong> chez la femme <span class=\"kw-clinique\">asymptomatique</span> sans <span class=\"kw-def\">facteur de risque</span> d'ostéoporose. <span class=\"kw-def\">Réévaluation</span> <span class=\"kw-chiffre\">annuelle</span>.</li>\n        <li><strong>IOP :</strong> balance différente → <span class=\"kw-ttt\">THM systématique</span> jusqu'à l'âge physiologique de la ménopause (bénéfice <span class=\"kw-alerte\">cardiovasculaire</span> et <span class=\"kw-alerte\">osseux</span>).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Symptôme cible</th><th>Alternatives au THM</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sécheresse vaginale</strong></td><td><span class=\"kw-ttt\">œstrogènes locaux</span> ; lubrifiants / hydratants non hormonaux</td></tr>\n          <tr><td><strong>Bouffées de chaleur</strong></td><td><span class=\"kw-ttt\">béta-alanine</span> (Abufène) ; <span class=\"kw-ttt\">ISRS/IRSNA</span> (hors AMM) ; phyto-œstrogènes (efficacité ≈ placebo, non recommandés HAS)</td></tr>\n          <tr><td><strong>Ostéoporose</strong></td><td><span class=\"kw-ttt\">SERM (raloxifène)</span> ; <span class=\"kw-ttt\">bisphosphonates</span> ; dénosumab</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-13","rang":"B","rubrique":"Prise en charge","titre":"Savoir informer des mesures éducatives et hygiéno-diététiques de la femme ménopausée","contenu":"<ul>\n        <li><strong><span class=\"kw-clinique\">Activité physique régulière</span></strong> (≈ <span class=\"kw-chiffre\">30-45 min</span> de marche rapide/jour) : prévention <span class=\"kw-alerte\">cardiovasculaire</span> et <span class=\"kw-alerte\">osseuse</span>.</li>\n        <li><strong>Apports calciques <span class=\"kw-chiffre\">1200-1500 mg/j</span></strong> + correction d'une carence en <span class=\"kw-bio\">vitamine D</span>.</li>\n        <li><span class=\"kw-clinique\">Arrêt du tabac</span> et limitation de l'<span class=\"kw-clinique\">alcool</span> (facteurs aggravant l'<span class=\"kw-alerte\">ostéoporose</span> et le <span class=\"kw-alerte\">risque cardiovasculaire</span>).</li>\n        <li><span class=\"kw-clinique\">Alimentation équilibrée</span> ; lutte contre la <span class=\"kw-clinique\">prise de poids</span>.</li>\n        <li>Information sur la ménopause, le <span class=\"kw-ttt\">THM</span> et ses alternatives ; <span class=\"kw-clinique\">dépistages</span> maintenus (<span class=\"kw-imagerie\">mammographie</span>, <span class=\"kw-bio\">frottis cervico-utérin</span>).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique.</em></p>","frequence":0},{"id":"124-14","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir que toute métrorragie chez une femme ménopausée doit être explorée afin d’éliminer un cancer endométrial","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Toute <span class=\"kw-alerte\">métrorragie post-ménopausique</span> est un <span class=\"kw-alerte\">cancer de l'endomètre</span> jusqu'à preuve du contraire → exploration <strong>systématique</strong>.\n      </div>\n      <p><strong>Conduite à tenir (Collège, item 43) :</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie pelvienne</span> par voie <strong>endovaginale</strong> (+ sus-pubienne) : apprécie l'<span class=\"kw-imagerie\">épaisseur et la régularité de l'endomètre</span> ; seuil d'alerte classique <span class=\"kw-chiffre\">endomètre &gt; 4 mm</span> chez la femme ménopausée (sans THM) → impose la <span class=\"kw-ttt\">biopsie</span>.</li>\n        <li><span class=\"kw-bio\">Biopsie d'endomètre</span> à la <strong>Pipelle de Cornier</strong> : indiquée chez toute patiente &gt; <span class=\"kw-chiffre\">45 ans</span> ou à risque de cancer de l'endomètre.</li>\n        <li><span class=\"kw-imagerie\">Hystéroscopie diagnostique</span> ± <span class=\"kw-ttt\">curetage</span> biopsique : visualise la cavité (polype, myome, aspect de l'endomètre).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La <span class=\"kw-bio\">biopsie d'endomètre</span> est faite à l'aveugle : même normale, elle <strong>n'élimine pas avec certitude</strong> un cancer de l'endomètre → poursuivre les explorations si saignement persistant.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 300 — Tumeur col-corps utérin</em></p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Gynécologie-obstétrique (items 124 et 43).</em></p>","frequence":0},{"id":"124-15","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’andropause ou du déficit androgénique lié à l’âge","contenu":"<p>Le terme préféré est <strong><span class=\"kw-def\">SDT (syndrome de déficit en testostérone)</span> lié à l'âge</strong>, à partir de <span class=\"kw-chiffre\">≥ 40 ans</span>. Le mot « <span class=\"kw-def\">andropause</span> » est <strong>inadéquat</strong> : contrairement à la ménopause, le <span class=\"kw-bio\">déficit en testostérone</span> est <span class=\"kw-clinique\">inconstant</span> et d'apparition <span class=\"kw-clinique\">progressive</span> (pas d'arrêt brutal de la <span class=\"kw-clinique\">fonction gonadique</span>).</p>\n      <p><strong>Définition ISSAM (2002) :</strong> <span class=\"kw-def\">syndrome biochimique</span> associé à l'<span class=\"kw-clinique\">avancée en âge</span>, caractérisé par une <span class=\"kw-bio\">diminution des androgènes</span> sériques ± diminution de la sensibilité aux androgènes, avec <span class=\"kw-clinique\">altération de la qualité de vie</span> et impact multi-organe.</p>\n      <p><strong>Rôles des androgènes</strong> (développement et maintien) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fonctions sexuelles et reproductives</span> masculines</li>\n        <li><span class=\"kw-clinique\">Composition corporelle</span> ; <span class=\"kw-bio\">érythropoïèse</span></li>\n        <li>Santé <span class=\"kw-clinique\">musculaire</span> et <span class=\"kw-clinique\">osseuse</span> ; <span class=\"kw-clinique\">fonctions cognitives</span> ; <span class=\"kw-clinique\">pilosité</span> et <span class=\"kw-clinique\">libido</span></li>\n      </ul>","frequence":0},{"id":"124-16","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’évolution de la fonction testiculaire avec l’âge","contenu":"<p>L'âge altère l'<span class=\"kw-def\">axe hypothalamo-hypophyso-gonadique</span> :</p>\n      <ul>\n        <li>↓ <span class=\"kw-bio\">stéroïdogenèse testiculaire</span> par <span class=\"kw-clinique\">diminution du nombre de cellules de Leydig</span></li>\n        <li>↓ amplitude des <span class=\"kw-bio\">pulses de GnRH</span> hypothalamiques</li>\n        <li>↓ concentration des <span class=\"kw-bio\">récepteurs des androgènes</span></li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span> :</strong> <span class=\"kw-def\">prévalence</span> ≈ <span class=\"kw-chiffre\">6 %</span> entre 30 et <span class=\"kw-chiffre\">80 ans</span>, croissante avec l'âge (<span class=\"kw-chiffre\">5 %</span> à<span class=\"kw-chiffre\"> 50 ans</span>, <span class=\"kw-chiffre\">10 %</span> à<span class=\"kw-chiffre\"> 60 ans</span>, <span class=\"kw-chiffre\">15 %</span> à<span class=\"kw-chiffre\"> 70 ans</span>, <span class=\"kw-chiffre\">26 %</span> à<span class=\"kw-chiffre\"> 80 ans</span>). <span class=\"kw-def\">Incidence</span> ≈ <span class=\"kw-chiffre\">12/10 000/an</span>.</p>\n      <table >\n        <thead><tr><th>Fraction de testostérone</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Liée à la <span class=\"kw-bio\">SHBG</span></strong> (≈ 2/3)</td><td>inactive ; la SHBG augmente avec l'âge → fausse la testostérone totale</td></tr>\n          <tr><td><strong>Liée à l'<span class=\"kw-bio\">albumine</span></strong></td><td>inactive mais facilement mobilisable</td></tr>\n          <tr><td><strong>Libre</strong> (≈ <span class=\"kw-chiffre\">2 %</span>)</td><td>fraction véritablement <strong>active</strong></td></tr>\n        </tbody>\n      </table>\n      <p>Testostérone <span class=\"kw-bio\">biodisponible</span> = <span class=\"kw-bio\">libre</span> + <span class=\"kw-bio\">liée à l'albumine</span> (échappe aux variations de la <span class=\"kw-bio\">SHBG</span>). Norme <span class=\"kw-bio\">testostérone totale</span> ≈ <span class=\"kw-chiffre\">3,5-10 ng/mL</span>.</p>","frequence":0},{"id":"124-17","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","contenu":"<p>Le diagnostic associe <strong>un <span class=\"kw-clinique\">syndrome clinique</span></strong> ET <strong>un <span class=\"kw-bio\">déficit biochimique</span></strong> confirmé.</p>\n      <table >\n        <thead><tr><th>Domaine clinique</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles sexuels</strong></td><td><span class=\"kw-clinique\">↓ érections nocturnes/matinales</span> (signe d'appel précoce et essentiel) ; <span class=\"kw-clinique\">dysfonction érectile</span> organique ; <span class=\"kw-clinique\">baisse de la libido</span> ; ↓ volume de l'éjaculat</td></tr>\n          <tr><td><strong>Vasomoteurs</strong></td><td><span class=\"kw-clinique\">bouffées de chaleur</span> ; <span class=\"kw-clinique\">sueurs</span> ; <span class=\"kw-clinique\">troubles du sommeil</span> ; fatigabilité musculaire</td></tr>\n          <tr><td><strong>Neuropsychologiques</strong></td><td><span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">humeur dépressive</span> ; <span class=\"kw-clinique\">irritabilité</span> ; troubles mémoire/concentration (aspécifiques)</td></tr>\n          <tr><td><strong>Signes physiques</strong></td><td><span class=\"kw-clinique\">sarcopénie</span> ; ↓ <span class=\"kw-imagerie\">DMO</span> (ostéopénie) ; <span class=\"kw-clinique\">obésité abdominale</span> / syndrome métabolique ; ↓ pilosité ; <span class=\"kw-clinique\">gynécomastie</span> ; <span class=\"kw-clinique\">atrophie testiculaire</span> ; <span class=\"kw-bio\">anémie normochrome normocytaire</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Le <span class=\"kw-bio\">score ADAM</span> objective les symptômes : positif si réponse oui aux questions <strong>1 (libido)</strong> et/ou <strong>7 (érections)</strong>, ou ≥ <span class=\"kw-chiffre\">3 réponses</span> positives. À la différence de la ménopause, <strong>pas d'arthralgie</strong> dans le SDT.\n      </div>\n      <p><strong>Confirmation biochimique</strong> (dosage le matin, entre <span class=\"kw-chiffre\">8 et 11 h</span>) :</p>\n      <ul>\n        <li>Déficit si <span class=\"kw-bio\">testostérone totale</span> &lt; <span class=\"kw-chiffre\">2,3 ng/mL</span> (&lt; 8 nmol/L).</li>\n        <li>Ou <span class=\"kw-bio\">testostérone totale</span> entre <span class=\"kw-chiffre\">2,3-3,5 ng/mL</span> <strong>ET</strong> <span class=\"kw-bio\">testostérone biodisponible</span> &lt; <span class=\"kw-chiffre\">0,7 ng/mL</span> ou <span class=\"kw-bio\">testostérone libre</span> &lt; <span class=\"kw-chiffre\">0,07 ng/mL</span>.</li>\n        <li>Tout dosage bas est <strong>recontrôlé</strong> <span class=\"kw-chiffre\">2 à 4 semaines</span> plus tard (avec <span class=\"kw-bio\">SHBG</span> et calcul de la <span class=\"kw-bio\">fraction libre</span>).</li>\n        <li>Orientation par <span class=\"kw-bio\">FSH/LH</span> : <strong>élevées</strong> → hypogonadisme <span class=\"kw-etio\">testiculaire</span> (primitif) ; <strong>basses/normales</strong> → hypogonadisme <span class=\"kw-etio\">hypogonadotrope</span> (central).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 246 — Gynécomastie</em></p>","frequence":4},{"id":"124-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels des déficits androgéniques liés à l’âge","contenu":"<p><strong>Diagnostics différentiels à éliminer :</strong> <span class=\"kw-etio\">vieillissement physiologique</span>, <span class=\"kw-etio\">hypothyroïdie</span> (<span class=\"kw-bio\">TSH</span>), <span class=\"kw-etio\">hyperprolactinémie</span> (adénome à prolactine), <span class=\"kw-etio\">hémochromatose</span>, hypogonadisme secondaire à une <span class=\"kw-etio\">maladie chronique</span> ou <span class=\"kw-etio\">iatrogène</span>.</p>\n      <table >\n        <thead><tr><th>Type d'hypogonadisme</th><th>Profil & étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Testiculaire primitif (ITP)</strong><br>= hypergonadotrope</td>\n            <td><strong>Profil :</strong> <span class=\"kw-bio\">testostérone basse</span> + <span class=\"kw-bio\">FSH/LH élevées</span><br><strong>Causes :</strong> <span class=\"kw-etio\">syndrome de Klinefelter</span> (47,XXY, +++) ; <span class=\"kw-etio\">chimiothérapie / radiothérapie</span> ; <span class=\"kw-etio\">alcoolisme chronique</span> ; <span class=\"kw-etio\">cryptorchidie bilatérale</span> ; <span class=\"kw-etio\">orchite ourlienne</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hypogonadotrope (HHA)</strong><br>= central</td>\n            <td><strong>Profil :</strong> <span class=\"kw-bio\">testostérone basse</span> + <span class=\"kw-bio\">FSH/LH basses ou normales</span><br><strong>Causes :</strong> <span class=\"kw-etio\">tumeurs hypothalamo-hypophysaires</span> (adénome, craniopharyngiome) ; <span class=\"kw-etio\">hyperprolactinémie</span> ; <span class=\"kw-etio\">hémochromatose</span> ; <span class=\"kw-etio\">iatrogène</span> (androgènes, <span class=\"kw-ttt\">corticoïdes</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Si <span class=\"kw-imagerie\">volume testiculaire</span> &lt; <span class=\"kw-chiffre\">4 mL</span> → réaliser un <span class=\"kw-bio\">caryotype</span> (recherche de <span class=\"kw-clinique\">syndrome de Klinefelter</span>).\n      </div>","frequence":0},{"id":"124-19","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les effets à court, moyen et long terme d’un déficit androgénique lié à l’âge non traité","contenu":"<table >\n        <thead><tr><th>Échéance</th><th>Conséquences du déficit non traité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Court terme</strong></td><td><span class=\"kw-clinique\">dysfonctions sexuelles</span> ; <span class=\"kw-clinique\">baisse de la libido</span> ; <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">troubles de l'humeur</span></td></tr>\n          <tr><td><strong>Moyen terme</strong></td><td>↓ <span class=\"kw-clinique\">masse et force musculaires</span> (<span class=\"kw-clinique\">sarcopénie</span>) ; <span class=\"kw-clinique\">troubles du métabolisme des graisses</span> ; <span class=\"kw-clinique\">obésité abdominale</span> ; <span class=\"kw-bio\">anémie</span></td></tr>\n          <tr><td><strong>Long terme</strong></td><td><span class=\"kw-alerte\">déminéralisation osseuse</span> / <span class=\"kw-alerte\">ostéoporose</span> ; <span class=\"kw-alerte\">troubles cognitifs</span> ; ↓ <span class=\"kw-clinique\">fertilité</span> ; <span class=\"kw-alerte\">syndrome métabolique</span> et risque <span class=\"kw-alerte\">cardiovasculaire</span></td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-7-item-124-andropause-syndrome-de-deficit-en-testosterone-lie-a-lage/","label":"Urofrance — référentiel item 124 (andropause / SDT)"},{"href":"https://www.sfendocrino.org/item-124-andropause/","label":"SF Endocrino — item 124 andropause"}],"cards":[{"i":"7f0e763eb061","n":124,"o":"124-1","u":"Définition","t":"Connaître la définition de la périménopause et ménopause","q":"Comment définir la périménopause et quelles en sont les caractéristiques principales ?","a":"<p>La périménopause est la <strong>période de transition précédant et incluant les 12 mois suivant</strong> les dernières règles. Elle se caractérise par :</p><ul><li>Des <strong>cycles menstruels irréguliers</strong> (raccourcis puis allongés), avec une variabilité de la durée <strong>supérieure à 7 jours</strong>.</li><li>Des <strong>signes climatériques débutants</strong>.</li><li>La persistance possible de <strong>menstruations sporadiques</strong> après une phase d'aménorrhée.</li><li>La <strong>FSH est fluctuante</strong>, reflétant l'épuisement folliculaire progressif.</li></ul>"},{"i":"c7fa92209765","n":124,"o":"124-1","u":"Définition","t":"Connaître la définition de la périménopause et ménopause","q":"Quelle est la définition de la ménopause ?","a":"<p>La ménopause est l'<strong>arrêt définitif des règles</strong>, secondaire à l'<strong>épuisement du capital folliculaire ovarien</strong>. C'est un diagnostic <strong>rétrospectif</strong>, posé après une <strong>aménorrhée d'au moins 12 mois consécutifs</strong>.</p>"},{"i":"44d870b97549","n":124,"o":"124-14","u":"Diagnostic positif","t":"Savoir que toute métrorragie chez une femme ménopausée doit être explorée afin d’éliminer un cancer endométrial","q":"Quel est le piège diagnostique à connaître concernant la biopsie d'endomètre par Pipelle de Cornier face à une métrorragie post-ménopausique ?","a":"<p>La biopsie d'endomètre à la Pipelle de Cornier est réalisée “à l'aveugle”. Même si son résultat est normal, <strong>elle n'élimine pas avec certitude un cancer de l'endomètre</strong> en cas de lésion focale manquée. Les explorations doivent être poursuivies si les saignements persistent.</p>"},{"i":"4e46549c4cd3","n":124,"o":"124-14","u":"Diagnostic positif","t":"Savoir que toute métrorragie chez une femme ménopausée doit être explorée afin d’éliminer un cancer endométrial","q":"Quels sont les examens diagnostiques complémentaires clés après l'échographie en cas de métrorragie post-ménopausique ?","a":"<ul><li>La <strong>biopsie d'endomètre à la Pipelle de Cornier</strong> : permet d'obtenir un prélèvement tissulaire pour analyse histologique. Elle est indiquée chez toute patiente de plus de 45 ans ou à risque de cancer de l'endomètre.</li><li>L'<strong>hystéroscopie diagnostique</strong>, éventuellement associée à un <strong>curetage biopsique</strong> : elle permet de visualiser directement la cavité utérine pour rechercher des anomalies focales (polype, myome, aspect de l'endomètre) et d'effectuer des prélèvements ciblés.</li></ul>"},{"i":"962aa004c821","n":124,"o":"124-14","u":"Diagnostic positif","t":"Savoir que toute métrorragie chez une femme ménopausée doit être explorée afin d’éliminer un cancer endométrial","q":"Quel est le premier examen à réaliser face à une métrorragie post-ménopausique, et quel seuil est alarmant pour l'endomètre ?","a":"<p>Le premier examen à réaliser est une <strong>échographie pelvienne par voie endovaginale</strong> (complétée si besoin par voie sus-pubienne). Un endomètre d'une épaisseur <strong>supérieure à 4 mm</strong> chez une femme ménopausée (ne recevant pas de THM) est un seuil d'alerte classique qui impose une exploration histologique.</p>"},{"i":"d34c40c3218a","n":124,"o":"124-14","u":"Diagnostic positif","t":"Savoir que toute métrorragie chez une femme ménopausée doit être explorée afin d’éliminer un cancer endométrial","q":"Comment doit être considérée toute métrorragie survenant chez une femme ménopausée, et quelle est l'attitude diagnostique initiale ?","a":"<p>Toute métrorragie survenant chez une femme ménopausée doit être considérée comme un <strong>cancer de l'endomètre jusqu'à preuve du contraire</strong>. Elle impose une <strong>exploration systématique</strong>.</p>"},{"i":"1d7ce91f8f2a","n":124,"o":"124-15","u":"Définition","t":"Connaître la définition de l’andropause ou du déficit androgénique lié à l’âge","q":"Quels sont les principaux rôles des androgènes (développement et maintien) dans l'organisme masculin ?","a":"<ul><li><strong>Fonctions sexuelles et reproductives</strong> masculines.</li><li>Régulation de la <strong>composition corporelle</strong> et de l'<strong>érythropoïèse</strong>.</li><li>Maintien de la <strong>santé musculaire et osseuse</strong>.</li><li>Influence sur les <strong>fonctions cognitives</strong>, la <strong>pilosité</strong> et la <strong>libido</strong>.</li></ul>"},{"i":"5af4697a082b","n":124,"o":"124-15","u":"Définition","t":"Connaître la définition de l’andropause ou du déficit androgénique lié à l’âge","q":"Pourquoi le terme « andropause » est-il considéré comme inadéquat pour décrire le déficit hormonal masculin lié à l'âge, comparé à la ménopause ?","a":"<p>Le terme « andropause » est jugé inadéquat car, contrairement à la ménopause qui implique un arrêt brutal de la fonction gonadique, le déficit en testostérone est <strong>inconstant</strong> et d'<strong>apparition progressive</strong>, sans arrêt brutal de la fonction gonadique masculine.</p>"},{"i":"9414054309c5","n":124,"o":"124-15","u":"Définition","t":"Connaître la définition de l’andropause ou du déficit androgénique lié à l’âge","q":"Selon la définition de l'ISSAM (2002), quelles sont les caractéristiques du Syndrome de Déficit en Testostérone (SDT) lié à l'âge ?","a":"<p>Selon l'ISSAM (2002), le SDT lié à l'âge est un syndrome biochimique associé à l'avancée en âge, caractérisé par :</p><ul><li>Une <strong>diminution des androgènes sériques</strong> (avec ou sans diminution de la sensibilité aux androgènes).</li><li>Une <strong>altération de la qualité de vie</strong>.</li><li>Un <strong>impact multi-organe</strong>.</li></ul>"},{"i":"94e196bbe9f8","n":124,"o":"124-15","u":"Définition","t":"Connaître la définition de l’andropause ou du déficit androgénique lié à l’âge","q":"Quel est le terme préféré pour décrire le déficit hormonal masculin lié à l'âge, et à partir de quel âge se manifeste-t-il communément ?","a":"<p>Le terme préféré est le <strong>Syndrome de Déficit en Testostérone (SDT) lié à l'âge</strong>. Il peut se manifester à partir de <strong>40 ans</strong>.</p>"},{"i":"069efb0c4d45","n":124,"o":"124-17","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","q":"Comment la FSH et la LH permettent-elles d'orienter le diagnostic étiologique de l'hypogonadisme dans le cadre d'une andropause ?","a":"<ul><li>Des taux de <strong>FSH/LH élevés</strong> orientent vers un <strong>hypogonadisme testiculaire (primitif)</strong>.</li><li>Des taux de <strong>FSH/LH bas/normaux</strong> orientent vers un <strong>hypogonadisme hypogonadotrope (central)</strong>.</li></ul>"},{"i":"0f67c13fed85","n":124,"o":"124-17","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","q":"Quels sont les principaux signes cliniques de l'andropause ?","a":"<ul><li><strong>Troubles sexuels</strong> : diminution des érections nocturnes/matinales (signe précoce essentiel), dysfonction érectile organique, baisse de la libido, diminution du volume de l'éjaculat.</li><li><strong>Signes vasomoteurs</strong> : bouffées de chaleur, sueurs, troubles du sommeil, fatigabilité musculaire.</li><li><strong>Signes neuropsychologiques</strong> : asthénie, humeur dépressive, irritabilité, troubles de la mémoire et de la concentration (ces derniers sont aspécifiques).</li><li><strong>Signes physiques</strong> : sarcopénie, diminution de la DMO (ostéopénie), obésité abdominale/syndrome métabolique, diminution de la pilosité, gynécomastie, atrophie testiculaire, anémie normochrome normocytaire.</li></ul>"},{"i":"1c18641f63d4","n":124,"o":"124-17","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","q":"Comment confirmer biologiquement le diagnostic d'andropause ?","a":"<p>La confirmation biologique repose sur le dosage de la testostérone le matin (entre 8h et 11h) :</p><ul><li><strong>Déficit si testostérone totale &lt; 2,3 ng/mL (&lt; 8 nmol/L)</strong>.</li><li>Ou si testostérone totale entre <strong>2,3 et 3,5 ng/mL</strong> ET testostérone biodisponible &lt; 0,7 ng/mL ou testostérone libre &lt; 0,07 ng/mL.</li></ul><p>Tout dosage bas doit être <strong>recontrôlé 2 à 4 semaines</strong> plus tard (avec SHBG et calcul de la fraction libre).</p>"},{"i":"1cf10428bf7a","n":124,"o":"124-17","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","q":"Comment pose-t-on le diagnostic d'andropause (ou SDT, Syndrome de Déficit en Testostérone) ?","a":"<p>Le diagnostic d'andropause (ou SDT) associe un <strong>syndrome clinique</strong> et un <strong>déficit biochimique confirmé</strong>.</p>"},{"i":"9275f2e66f7e","n":124,"o":"124-17","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic d’andropause","q":"Quel score clinique peut aider à objectiver les symptômes de l'andropause ?","a":"<p>Le <strong>score ADAM</strong> objective les symptômes. Il est considéré positif si le patient répond 'oui' aux questions 1 (libido) et/ou 7 (érections), ou s'il y a <strong>≥ 3 réponses positives</strong> au total.</p>"},{"i":"83799f4be0b9","n":124,"o":"124-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic de ménopause","q":"Quelles sont les anomalies des dosages hormonaux qui confirment le diagnostic de ménopause ?","a":"<p>Lorsque les dosages hormonaux sont réalisés, la ménopause est confirmée par une <strong>FSH supérieure à 20 UI/L</strong> et un taux d'<strong>estradiol (E2) inférieur à 20 pg/mL</strong>.</p>"},{"i":"85d3e0c0f699","n":124,"o":"124-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic de ménopause","q":"Quel est l'intérêt du test au progestatif dans le diagnostic de la ménopause, et quelle est son interprétation ?","a":"<p>Le test au progestatif est utilisé en cas d'aménorrhée de <strong>moins de 12 mois</strong>. La prise de progestatif pendant <strong>10 à 12 jours</strong> permet de confirmer l'hypoœstrogénie si le test est <strong>négatif</strong> (absence d'hémorragie de privation, signifiant que l'endomètre n'a pas été suffisamment stimulé par les œstrogènes). Un test positif témoigne d'une activité ovarienne persistante.</p>"},{"i":"cb5d069efece","n":124,"o":"124-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic de ménopause","q":"Dans quelles situations les dosages hormonaux sont-ils justifiés pour le diagnostic de ménopause ?","a":"<p>Les dosages hormonaux ne sont <strong>pas systématiques</strong> et ne sont utiles que dans des situations de doute diagnostique ou lorsque les critères cliniques sont incomplets :</p><ul><li>Après une <strong>hystérectomie</strong> (absence de repère menstruel).</li><li>En cas d'<strong>âge inhabituel</strong> (avant 50 ans).</li><li>En cas de <strong>doute diagnostique</strong> malgré la clinique.</li></ul>"},{"i":"d77b1fa9b9a9","n":124,"o":"124-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques positifs et/ou biologiques qui permettent de poser le diagnostic de ménopause","q":"Quels sont les critères cliniques permettant de poser le diagnostic de ménopause ?","a":"<p>Le diagnostic de ménopause est posé cliniquement sur l'association d'une <strong>aménorrhée depuis au moins 12 mois</strong> chez une femme d'environ <strong>50 ans</strong>, et la présence d'un <strong>syndrome climatérique</strong>.</p>"},{"i":"54a1823fa6de","n":124,"o":"124-5","u":"Diagnostic positif","t":"Connaître les symptômes du syndrome climatérique","q":"Quelle est l'étiologie principale du syndrome climatérique ?","a":"<p>Le syndrome climatérique est la conséquence d'une <strong>hypoœstrogénie</strong> chez la femme.</p>"},{"i":"5ef3a618be3b","n":124,"o":"124-5","u":"Diagnostic positif","t":"Connaître les symptômes du syndrome climatérique","q":"Quels sont les symptômes généraux et psycho-affectifs associés au syndrome climatérique ?","a":"<ul><li><strong>Symptômes généraux</strong> : troubles du sommeil, céphalées, arthralgies.</li><li><strong>Symptômes psycho-affectifs</strong> : troubles de l'humeur, irritabilité, baisse de la libido.</li></ul>"},{"i":"619e7131b5ec","n":124,"o":"124-5","u":"Diagnostic positif","t":"Connaître les symptômes du syndrome climatérique","q":"Quels sont les symptômes génito-urinaires pouvant être présents dans le cadre du syndrome climatérique ?","a":"<ul><li>La <strong>sécheresse vaginale</strong>.</li><li>La <strong>dyspareunie</strong>.</li><li>Des <strong>troubles urinaires</strong>.</li></ul>"},{"i":"766f7b01a6f4","n":124,"o":"124-5","u":"Diagnostic positif","t":"Connaître les symptômes du syndrome climatérique","q":"Quels sont les principaux symptômes neuro-végétatifs (vasomoteurs) du syndrome climatérique ?","a":"<ul><li>Les <strong>bouffées de chaleur</strong> (présentes chez environ 65% des femmes).</li><li>Les <strong>sueurs nocturnes</strong>.</li></ul>"},{"i":"133308dbf3c0","n":124,"o":"124-7","u":"Diagnostic positif","t":"Connaître les signes d’hypoœstrogénie, d’hyperœstrogénie","q":"Quels sont les signes cliniques qui caractérisent l'hypoœstrogénie ?","a":"<ul><li><strong>Atrophie vulvo-vaginale</strong> se manifestant par une sécheresse, une dyspareunie et un prurit.</li><li>Absence de <strong>glaire cervicale</strong> avec test au progestatif négatif.</li><li><strong>Troubles urinaires</strong> tels que dysurie, urgenturie et incontinence.</li><li><strong>Bouffées de chaleur</strong>.</li><li><strong>Vieillissement cutané et des phanères</strong>.</li></ul>"},{"i":"405d974bb080","n":124,"o":"124-7","u":"Diagnostic positif","t":"Connaître les signes d’hypoœstrogénie, d’hyperœstrogénie","q":"Quels sont les signes cliniques de l'hyperœstrogénie ?","a":"<ul><li><strong>Mastodynie</strong> ou tension mammaire, qui est le signe le plus direct.</li><li><strong>Ménométrorragies fonctionnelles</strong>.</li><li><strong>Hyperplasie endométriale</strong>.</li><li><strong>Glaire cervicale abondante</strong>.</li><li><strong>Rétention hydrosodée</strong> entraînant œdèmes, prise de poids et gonflement abdominal.</li><li>Irritabilité.</li><li>Signes de surdosage œstrogénique en cas de Traitement Hormonal de la Ménopause (THM).</li></ul>"},{"i":"c1a429830e90","n":124,"o":"124-7","u":"Diagnostic positif","t":"Connaître les signes d’hypoœstrogénie, d’hyperœstrogénie","q":"Quelle est la principale conséquence de l'hyperœstrogénie non opposée (sans progestatif) et sa prise en charge en cas de Traitement Hormonal de la Ménopause (THM) ?","a":"<p>L'hyperœstrogénie non opposée favorise l'apparition d'une <strong>hyperplasie de l'endomètre</strong> qui peut évoluer vers un <strong>cancer de l'endomètre</strong>. Cela justifie l'ajout systématique d'un <strong>progestatif</strong> chez la femme non hystérectomisée recevant des œstrogènes.</p>"}]};